SELECT m.sponsorId, s.companyName, m.timeSlot, m.attendeeNumber, m.sponsorRepName
FROM meetings m
JOIN sponsors s ON m.sponsorId = s.id
WHERE m.attendeeId = '452351'
ORDER BY m.sponsorId;

SELECT id, companyName FROM sponsors WHERE companyName LIKE '%hackajob%' OR companyName LIKE '%Appcast%' OR companyName LIKE '%appcast%';
